DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.product_asset_declaration_valid(text,text,text,text,text,text)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='b87368e0acec871cf7344c7adb4029a8de70a107a039ead14d118b3cadd7d12e' AND proowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AND proconfig=ARRAY['search_path=pg_catalog'] AND NOT prosecdef) THEN RAISE EXCEPTION 'KNOWN_TEN_HELPER_CHANGED:product_asset_declaration_valid' USING ERRCODE='55000'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.internal_review_valid(qf.draft_review)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='26ede0af9cad05945388bf68ef40fa99fcc2d09b7980c9e399eb340f661bdd8d' AND proowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AND proconfig=ARRAY['search_path=pg_catalog'] AND NOT prosecdef) THEN RAISE EXCEPTION 'KNOWN_TEN_HELPER_CHANGED:internal_review_valid' USING ERRCODE='55000'; END IF; END $$;

