CREATE OR REPLACE FUNCTION qf.private_test_database_valid() RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT (current_database()='qf_db_953991305a7e8c49bb773d95cd120378' AND shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')='quizforge.p2a.v1:953991305a7e8c49bb773d95cd120378:test') OR (current_database()='qf_db_bea112ce460725bd10fc41226e45df48' AND shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')='quizforge.p2a.v1:bea112ce460725bd10fc41226e45df48:test') OR (current_database()='qf_db_601707c7f4511e7d6fb09da3a907c8d9' AND shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')='quizforge.p2a.v1:601707c7f4511e7d6fb09da3a907c8d9:test') OR (current_database()='qf_db_79331f888c569d9fbf7a2a08e5f33f68' AND shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')='quizforge.p2a.v1:79331f888c569d9fbf7a2a08e5f33f68:test') OR (current_database()='qf_db_b3d733d96206b456072dcf5609d52e32' AND shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')='quizforge.p2a.v1:b3d733d96206b456072dcf5609d52e32:test') $$;

CREATE OR REPLACE FUNCTION qf.private_test_structure_valid(source jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE marked boolean; private_count integer; total integer;
BEGIN
 marked:=(source->'bindings') ? 'privateTestUse';
 SELECT count(*)::integer,count(*) FILTER(WHERE r->>'approval'='private-test-only')::integer INTO total,private_count FROM jsonb_array_elements(source#>'{bindings,resources}') r;
 IF NOT marked THEN RETURN private_count=0; END IF;
 RETURN (total>0 AND total=private_count AND source#>>'{bindings,kind}'='authored'
  AND (source#>'{bindings,privateTestUse}'='{"authorizationId":"qztx-known-ten-private-20261104","contentStatus":"candidate","instanceId":"b3d733d96206b456072dcf5609d52e32","resourceStatus":"reference-or-candidate","schemaVersion":"quizforge.private-test-use.v1"}'::jsonb OR source#>'{bindings,privateTestUse}'='{"authorizationId":"qztx-full-flow-20261030","contentStatus":"candidate","instanceId":"953991305a7e8c49bb773d95cd120378","resourceStatus":"reference-or-candidate","schemaVersion":"quizforge.private-test-use.v1"}'::jsonb OR (source#>'{bindings,privateTestUse}'='{"authorizationId":"qztx-prototype-rebuild-20261031","contentStatus":"candidate","instanceId":"bea112ce460725bd10fc41226e45df48","resourceStatus":"reference-or-candidate","schemaVersion":"quizforge.private-test-use.v1"}'::jsonb OR source#>'{bindings,privateTestUse}'='{"authorizationId":"qztx-final-private-20261103","contentStatus":"candidate","instanceId":"601707c7f4511e7d6fb09da3a907c8d9","resourceStatus":"reference-or-candidate","schemaVersion":"quizforge.private-test-use.v1"}'::jsonb OR source#>'{bindings,privateTestUse}'='{"authorizationId":"qztx-final-private-20261103","contentStatus":"candidate","instanceId":"79331f888c569d9fbf7a2a08e5f33f68","resourceStatus":"reference-or-candidate","schemaVersion":"quizforge.private-test-use.v1"}'::jsonb))
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source#>'{bindings,resources}') r WHERE r#>'{license,commercialUse}' IS DISTINCT FROM 'false'::jsonb OR r#>'{license,redistribution}' IS DISTINCT FROM 'false'::jsonb OR r#>>'{license,scope}' IS DISTINCT FROM 'private-test-only')) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.private_test_source_valid(source jsonb,asset_sha text,manifest_sha text) RETURNS boolean LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog AS $$
BEGIN
 IF coalesce((source->'bindings') ? 'privateTestUse',false) IS FALSE THEN RETURN true; END IF;
